def _create_metrics(meter: Meter):
    token_histogram = meter.create_histogram(
        name=Meters.LLM_TOKEN_USAGE,
        unit="token",
        description="Measures number of input and output tokens used",
    )

    choice_counter = meter.create_counter(
        name=Meters.LLM_GENERATION_CHOICES,
        unit="choice",
        description="Number of choices returned by chat completions call",
    )

    duration_histogram = meter.create_histogram(
        name=Meters.LLM_OPERATION_DURATION,
        unit="s",
        description="GenAI operation duration",
    )

    return token_histogram, choice_counter, duration_histogram


def _process_streaming_chunk(chunk):
    """Extract content, tool call deltas, finish reasons and usage from a chunk.

    Returns a 4-tuple ``(content, tool_calls_delta, finish_reasons, usage)``.
    When ``chunk.choices`` is empty, returns ``(None, [], [], None)``.
    """
    if not chunk.choices:
        return None, [], [], None

    delta = chunk.choices[0].delta
    content = delta.content if hasattr(delta, "content") else None
    tool_calls_delta = getattr(delta, "tool_calls", None) or []

    finish_reasons = []
    for choice in chunk.choices:
        if getattr(choice, "finish_reason", None):
            finish_reasons.append(choice.finish_reason)

    # Extract usage from x_groq if present in the final chunk
    usage = None
    if hasattr(chunk, "x_groq") and chunk.x_groq and chunk.x_groq.usage:
        usage = chunk.x_groq.usage

    return content, tool_calls_delta, finish_reasons, usage


def _accumulate_tool_calls(acc, delta_list):
    """Accumulate tool call deltas into ``acc`` keyed by index."""
    for tool_call in delta_list:
        if isinstance(tool_call, dict):
            index = tool_call.get("index", 0)
            tc_id = tool_call.get("id")
            function = tool_call.get("function") or {}
            name = function.get("name") if isinstance(function, dict) else None
            arguments = (
                function.get("arguments") if isinstance(function, dict) else None
            )
        else:
            index = getattr(tool_call, "index", 0)
            tc_id = getattr(tool_call, "id", None)
            function = getattr(tool_call, "function", None)
            name = getattr(function, "name", None) if function else None
            arguments = getattr(function, "arguments", None) if function else None

        entry = acc.setdefault(
            index, {"id": None, "function": {"name": "", "arguments": ""}}
        )
        if tc_id:
            entry["id"] = tc_id
        if name:
            entry["function"]["name"] = name
        if arguments:
            entry["function"]["arguments"] += arguments


def _accumulated_tool_calls_to_list(acc):
    return [acc[index] for index in sorted(acc.keys())]


def _handle_streaming_response(
    span, accumulated_content, tool_calls_acc, finish_reasons, usage, event_logger
):
    set_model_streaming_response_attributes(span, usage, finish_reasons)
    finish_reason = finish_reasons[-1] if finish_reasons else None
    if should_emit_events() and event_logger:
        emit_streaming_response_events(accumulated_content, finish_reason, event_logger)
    else:
        tool_calls = _accumulated_tool_calls_to_list(tool_calls_acc)
        set_streaming_response_attributes(
            span, accumulated_content, finish_reason, tool_calls
        )


def _create_stream_processor(response, span, event_logger):
    """Create a generator that processes a stream while collecting telemetry."""
    accumulated_content = ""
    tool_calls_acc = {}
    finish_reasons = []
    usage = None

    for chunk in response:
        content, tool_calls_delta, chunk_finish_reasons, chunk_usage = (
            _process_streaming_chunk(chunk)
        )
        if content:
            accumulated_content += content
        if tool_calls_delta:
            _accumulate_tool_calls(tool_calls_acc, tool_calls_delta)
        for finish_reason in chunk_finish_reasons:
            if finish_reason not in finish_reasons:
                finish_reasons.append(finish_reason)
        if chunk_usage:
            usage = chunk_usage
        yield chunk

    _handle_streaming_response(
        span, accumulated_content, tool_calls_acc, finish_reasons, usage, event_logger
    )

    if span.is_recording():
        span.set_status(Status(StatusCode.OK))

    span.end()


